// Validate & parse incoming TradingView signal
const body = $input.first().json.body || $input.first().json;

const required = ['symbol', 'action', 'price'];
for (const field of required) {
  if (!body[field]) throw new Error(`Missing required field: ${field}`);
}

const action = (body.action || '').toUpperCase();
if (!['BUY', 'SELL'].includes(action)) {
  throw new Error(`Invalid action: ${action}. Must be BUY or SELL`);
}

return [{
  json: {
    symbol:    (body.symbol || 'NIFTY').toUpperCase(),
    action:    action,
    price:     parseFloat(body.price),
    strategy:  body.strategy  || 'Unknown',
    timeframe: body.timeframe || '5',
    timestamp: new Date().toISOString(),
    secret:    body.secret    || ''
  }
}];

