const response = $input.first().json;
const signal   = $('Validate Signal').first().json;

let marketData = {};
try {
  const content = response.content || [];
  const textBlock = content.find(b => b.type === 'text');
  let text = textBlock ? textBlock.text.trim() : '{}';
  if (text.startsWith('```')) {
    text = text.replace(/```json\n?|```/g, '').trim();
  }
  marketData = JSON.parse(text);
} catch(e) {
  marketData = { current_price: signal.price, vix: 15, vix_level: 'moderate', pcr: 1.0, sentiment: 'neutral' };
}

return [{ json: { signal, marketData } }];

