// Parse Risk Management Agent response
const response = $input.first().json;
const prev     = $('Parse Signal Analysis').first().json;

let riskData = {};
try {
  const content = response.content || [];
  const textBlock = content.find(b => b.type === 'text');
  let text = textBlock ? textBlock.text.trim() : '{}';
  if (text.startsWith('```')) {
    text = text.replace(/```json\n?|```/g, '').trim();
  }
  riskData = JSON.parse(text);
} catch(e) {
  riskData = { approved: false, qty: 0, stop_loss: 0, target: 0, reason: 'Risk parse error' };
}

// Calculate target using 1:2 R:R if not provided
if (riskData.approved && (!riskData.target || riskData.target === 0)) {
  const entry = prev.signal.price;
  const sl    = riskData.stop_loss || (prev.signal.action === 'BUY' ? entry - 150 : entry + 150);
  const risk  = Math.abs(entry - sl);
  riskData.target = prev.signal.action === 'BUY' ? entry + 2 * risk : entry - 2 * risk;
}

return [{ json: { ...prev, riskData } }];

const data = $input.first().json;
return [{
  json: {
    decision:    'TRADE_BLOCKED',
    symbol:      data.signal.symbol,
    action:      data.signal.action,
    order_id:    null,
    entry_price: data.signal.price,
    qty:         0,
    stop_loss:   0,
    target:      0,
    reason:      data.riskData.reason || 'Trade blocked by risk management',
    agent_results: {
      market_data:     data.marketData,
      signal_analysis: data.signalAnalysis,
      risk_management: data.riskData,
      trade_execution: null
    }
  }
}];

