// Parse Trade Execution Agent response
const response = $input.first().json;
const prev     = $('Parse Risk Data').first().json;

let execData = {};
try {
  const content = response.content || [];
  const textBlock = content.find(b => b.type === 'text');
  let text = textBlock ? textBlock.text.trim() : '{}';
  if (text.startsWith('```')) {
    text = text.replace(/```json\n?|```/g, '').trim();
  }
  execData = JSON.parse(text);
} catch(e) {
  const now = new Date().toISOString().replace(/[-:.T]/g,'').slice(0,14);
  execData = {
    order_id:    `PAPER_${now}_${Math.floor(Math.random()*9000)+1000}`,
    status:      'FILLED',
    symbol:      prev.signal.symbol,
    action:      prev.signal.action,
    qty:         prev.riskData.qty,
    entry_price: prev.signal.price,
    stop_loss:   prev.riskData.stop_loss,
    target:      prev.riskData.target,
    message:     `📊 PAPER TRADE\n${prev.signal.action} ${prev.signal.symbol} @ ₹${prev.signal.price}\nQty: ${prev.riskData.qty} | SL: ₹${prev.riskData.stop_loss} | Target: ₹${prev.riskData.target}`,
    logged:      true
  };
}

const finalResult = {
  decision:    'TRADE_PLACED',
  symbol:      prev.signal.symbol,
  action:      prev.signal.action,
  order_id:    execData.order_id,
  entry_price: execData.entry_price || prev.signal.price,
  qty:         execData.qty         || prev.riskData.qty,
  stop_loss:   execData.stop_loss   || prev.riskData.stop_loss,
  target:      execData.target      || prev.riskData.target,
  reason:      `${prev.signal.strategy} — ${prev.signalAnalysis.reason || 'AI-confirmed signal'}`,
  telegram_msg: execData.message,
  agent_results: {
    market_data:     prev.marketData,
    signal_analysis: prev.signalAnalysis,
    risk_management: prev.riskData,
    trade_execution: execData
  }
};

return [{ json: finalResult }];

// Merge all pipeline results into one for Telegram & response
const items = $input.all();
return items.map(item => ({ json: item.json }));

